"use client";

import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import type { ParsedFeature, ParsedTask } from "@/services/yaml-parser";
import type { StoredWorkspace } from "@/types/workspace";
import { useBoardData, type UseBoardDataOptions } from "../../hooks/useBoardData";
import type { ActiveFilters, BoardLoadError } from "../../types";

export type SelectedTask = {
  task: ParsedTask;
  featureId: string;
  featureTitle: string;
} | null;

export type BoardContextValue = {
  workspace: StoredWorkspace;
  features: ParsedFeature[];
  loading: boolean;
  error: BoardLoadError | null;
  reload: () => void;
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  activeFilters: ActiveFilters;
  setActiveFilters: (filters: ActiveFilters) => void;
  expandedFeatureIds: Set<string>;
  toggleFeature: (featureId: string) => void;
  selectedTask: SelectedTask;
  setSelectedTask: (task: SelectedTask) => void;
};

const BoardContext = createContext<BoardContextValue | null>(null);

export type BoardProviderProps = {
  workspace: StoredWorkspace;
  children: ReactNode;
} & UseBoardDataOptions;

export function BoardProvider({
  workspace,
  children,
  clientFactory,
}: BoardProviderProps) {
  const { features, loading, error, reload } = useBoardData(workspace, {
    clientFactory,
  });

  const [searchQuery, setSearchQuery] = useState("");
  const [activeFilters, setActiveFilters] = useState<ActiveFilters>({
    statuses: [],
  });
  const [expandedFeatureIds, setExpandedFeatureIds] = useState<Set<string>>(
    () => new Set(),
  );
  const [selectedTask, setSelectedTask] = useState<SelectedTask>(null);

  const toggleFeature = useCallback((featureId: string) => {
    setExpandedFeatureIds((prev) => {
      const next = new Set(prev);
      if (next.has(featureId)) {
        next.delete(featureId);
      } else {
        next.add(featureId);
      }
      return next;
    });
  }, []);

  const value = useMemo<BoardContextValue>(
    () => ({
      workspace,
      features,
      loading,
      error,
      reload,
      searchQuery,
      setSearchQuery,
      activeFilters,
      setActiveFilters,
      expandedFeatureIds,
      toggleFeature,
      selectedTask,
      setSelectedTask,
    }),
    [
      workspace,
      features,
      loading,
      error,
      reload,
      searchQuery,
      activeFilters,
      expandedFeatureIds,
      toggleFeature,
      selectedTask,
    ],
  );

  return <BoardContext.Provider value={value}>{children}</BoardContext.Provider>;
}

export function useBoardContext(): BoardContextValue {
  const ctx = useContext(BoardContext);
  if (!ctx) {
    throw new Error("useBoardContext must be used within a BoardProvider");
  }
  return ctx;
}

export {
  BoardProvider,
  useBoardContext,
  type BoardContextValue,
  type BoardProviderProps,
  type SelectedTask,
} from "./KanbanBoard.context";

